def proc_data(df):
  df['player_to_predict'] = pd.Categorical(df['player_to_predict'])
  df['nfl_id'] = pd.Categorical(df['nfl_id'])
  df['play_direction'] = pd.Categorical(df['play_direction'])
  df['player_height'] = (df['player_height'].str.split('-', expand=True)[0].astype(int) * 12 +
                        df['player_height'].str.split('-', expand=True)[1].astype(int))
  df['player_birth_date'] = pd.to_datetime(df['player_birth_date'], format="%Y-%m-%d")
  df['player_position'] = pd.Categorical(df['player_position'])
  df['player_side'] = pd.Categorical(df['player_side'])
  df['player_role'] = pd.Categorical(df['player_role'])
  df['game_dates'] = pd.to_datetime(df['game_id'].astype(str).str[:8], format='%Y%m%d')
  df['age'] = ((df['game_dates'] - df['player_birth_date']).dt.days // 365)

proc_data(df)

