import polars as pl; import kaggle_evaluation.nfl_inference_server

def predict(test: pl.DataFrame, test_input: pl.DataFrame) -> pl.DataFrame:
  df_tinps = test_input.to_pandas()
  df_test = test.to_pandas()
  df = df_test.merge(df_tinps, on=['game_id', 'play_id', 'nfl_id', 'frame_id'],
                     how='left', suffixes=('', '_feat')) # this suffixes is useful
  feature_cols = [c for c in df_tinps.columns if c not in ['game_id', 'play_id', 'nfl_id',
                                                           'frame_id']]
  df = df.sort_values(['game_id', 'play_id', 'nfl_id', 'frame_id'])
  df[feature_cols] = (df.groupby(['game_id', 'play_id', 'nfl_id'])[feature_cols].ffill())

  proc_data(df)
  df[cats] = df[cats].apply(lambda x: x.cat.codes) # convert cats to codes
  test_xs, _ = xs_y(df) # get features
  preds = m50.predict(test_xs) # make preds

  if 'x' in df.columns and 'y' in df.columns:
    y_true = df[['x','y']].to_numpy()
    rmse = root_mean_squared_error(preds, y_true)
    print(f"RMSE: {rmse:.4f}")
  else: print("Ground truth missing. Skipping RMSE log.")
  return pl.DataFrame({'x': preds[:,0], 'y': preds[:,1]}) # create output df with x and y cols

"""What does suffixes=('', '_feat') mean?

When you merge two DataFrames in pandas, any columns with the same name (other than the merge keys) will cause a name collision. Pandas handles this by adding suffixes to those overlapping column names.

For example:

Suppose:

df_test has columns:
['game_id', 'play_id', 'nfl_id', 'frame_id', 'x', 'y']

df_tinps has columns:
['game_id', 'play_id', 'nfl_id', 'frame_id', 'x', 'y', 'speed', 'acceleration']

Then merging like this:

df_test.merge(df_tinps, on=['game_id', 'play_id', 'nfl_id', 'frame_id'], how='left')


will result in:

['game_id', 'play_id', 'nfl_id', 'frame_id', 'x_x', 'y_x', 'x_y', 'y_y', 'speed', 'acceleration']


That x_x, x_y, etc. stuff is pandas auto-renaming:

_x is added to the version coming from the left DataFrame (df_test)

_y is added to the version from the right DataFrame (df_tinps)

But often, especially in inference, df_test is mostly just the keys and maybe some metadata. You probably want to keep the “model input” values from df_tinps and ignore the ones from df_test (or vice versa).

So, what does suffixes=('', '_feat') do?

This explicitly says:

“When naming collisions occur, leave the left-hand side (from df_test) untouched (suffix=''), and append _feat to the right-hand side (from df_tinps).”

So after merging you'd get:

['game_id', 'play_id', 'nfl_id', 'frame_id', 'x', 'y', 'x_feat', 'y_feat', 'speed', 'acceleration']


Now you can clearly distinguish:

The original x, y from the test file, if they exist.

The _feat versions that represent model features (from test_input).

Other computed columns like speed and acceleration.
"""

inference_server = kaggle_evaluation.nfl_inference_server.NFLInferenceServer(predict)

inference_server.run_local_gateway((path,))

